import{_ as o,o as a,c as d,ae as t}from"./chunks/framework.YL6nI5ZP.js";const h=JSON.parse('{"title":"Map & Rendering Layer","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/03-map-and-rendering.md","filePath":"explanation/03-map-and-rendering.md"}'),s={name:"explanation/03-map-and-rendering.md"};function r(c,e,l,n,i,p){return a(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="map-rendering-layer" tabindex="-1">Map &amp; Rendering Layer <a class="header-anchor" href="#map-rendering-layer" aria-label="Permalink to &quot;Map &amp; Rendering Layer&quot;">​</a></h1><p>How Mapbox GL JS is used as the canvas for the whole editor: the map instance, the source/layer stack, styling through feature-state, re-render behavior, DEM sampling, and the overlays on top.</p><h2 id="map-initialization-—-app-js" tabindex="-1">Map initialization — <code>app.js</code> <a class="header-anchor" href="#map-initialization-—-app-js" aria-label="Permalink to &quot;Map initialization — `app.js`&quot;">​</a></h2><ul><li>Default view: La Serena, Chile (<code>DEFAULT_CENTER = [-71.254, -29.908]</code>, <code>DEFAULT_ZOOM = 15.2</code> — <code>app.js:7-8</code>).</li><li><code>MAP_STYLES</code> (<code>app.js:16-25</code>): <code>streets</code> (<code>mapbox://styles/mapbox/streets-v12</code>), <code>satellite</code> (<code>satellite-streets-v12</code>), and a hand-built <code>blank</code> style (light background).</li><li><code>new mapboxgl.Map({… pitch:0, bearing:0, antialias:true, boxZoom:false })</code> stored as <code>window.map</code> (<code>app.js:27-38</code>), plus Navigation + Scale controls.</li></ul><h2 id="layer-stack-—-ensurenetworklayers-app-js-114-274" tabindex="-1">Layer stack — <code>ensureNetworkLayers</code> (<code>app.js:114-274</code>) <a class="header-anchor" href="#layer-stack-—-ensurenetworklayers-app-js-114-274" aria-label="Permalink to &quot;Layer stack — `ensureNetworkLayers` (`app.js:114-274`)&quot;">​</a></h2><p>Sources and layers (source → layer ids):</p><table tabindex="0"><thead><tr><th>Source</th><th>Layers</th><th>Purpose</th></tr></thead><tbody><tr><td><code>draft</code></td><td><code>draft-line/fill/points</code></td><td>Ghost geometry while drawing</td></tr><tr><td><code>swmm-2d-mesh</code></td><td><code>swmm-2d-mesh-fill</code>, <code>swmm-2d-mesh-line</code></td><td>2D mesh cells (fill colored by results)</td></tr><tr><td><code>swmm-subcatchments</code></td><td><code>swmm-subcatchments-fill</code>, <code>swmm-subcatchments-line</code> (dashed)</td><td>Drainage areas</td></tr><tr><td><code>swmm-links</code></td><td><code>swmm-links-hit</code> (invisible 14 px), <code>swmm-links-layer</code>, <code>swmm-links-arrows</code></td><td>Links + flow arrows</td></tr><tr><td><code>swmm-nodes</code></td><td><code>swmm-nodes-layer</code> (circle, <code>promoteId:&#39;id&#39;</code>), <code>swmm-nodes-labels</code></td><td>Nodes + labels</td></tr><tr><td>master plan / constraints</td><td>—</td><td>Imported background layers</td></tr></tbody></table><p><strong>Styling architecture:</strong> color expressions <code>nodeColorExpr/linkColorExpr</code> (<code>app.js:77-89</code>) compose with <code>selectedCase(sel,hov,base)</code> (<code>app.js:91-94</code>) and <code>resultOr(base)</code> (<code>app.js:97-99</code>), which lets simulation result colors override base colors through Mapbox <strong>feature-state</strong> (<code>selected</code>, <code>hovered</code>, <code>resultColor</code>) — set via <code>window.setElementState</code> (<code>app.js:320-325</code>). This is why selection/hover/result styling needs no data re-send.</p><h2 id="re-render-dem" tabindex="-1">Re-render &amp; DEM <a class="header-anchor" href="#re-render-dem" aria-label="Permalink to &quot;Re-render &amp; DEM&quot;">​</a></h2><ul><li><code>refreshNetworkData()</code> (<code>app.js:276-293</code>) resends all sources + restores selection feature-state; <code>refreshNetworkDataForMove()</code> (<code>app.js:299-310</code>) is rAF-throttled and updates only nodes/links during drags.</li><li><code>map.on(&#39;style.load&#39;)</code> (<code>app.js:622-629</code>) re-runs layer creation after basemap swaps.</li><li><strong>DEM elevation sampling</strong> (<code>sampleDEMElevationAsync</code>, <code>app.js:437-495</code>): (1) in-memory mesh terrain sampler, else (2) OpenTopography point API for non-Mapbox sources (COP30/USGS10m/SRTMGL1/NASADEM/ANADEM/GEDTM30), else (3) Mapbox terrain-DEM + <code>map.queryTerrainElevation</code>. <code>sampleAllNodesDEM()</code> (<code>app.js:522-543</code>) loops all nodes. The synchronous variant (<code>sampleDEMElevation</code>, <code>app.js:497-520</code>) runs at node placement.</li></ul><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to &quot;Overlays&quot;">​</a></h2><ul><li><strong>Street View:</strong> <code>street_view_overlay.js</code> (pegman + overlay), requires <code>GOOGLE_MAPS_API_KEY</code>.</li><li><strong>OSM search:</strong> <code>#osm-search</code> geocodes via OpenStreetMap.</li><li><strong>Time slider:</strong> <code>AnimationUI</code> (<code>ui.js:1086-1152</code>) — <code>setRange(maxSteps)</code>, <code>updateDisplay()</code> (calls <code>ResultStyling.applyToMapForStep</code>, <code>Tools.updateHoverPopup</code>, <code>ProfilePlot.update</code>, <code>StreetViewOverlay.scheduleRedraw</code>), <code>play()</code> (rAF loop at 500 ms/speed).</li><li><strong>2D overlays:</strong> GeoJSON isolines/bands/arrows (<code>mesh2dRender.js</code>) and a WebGL2 Gouraud custom layer (<code>meshGlLayer.js</code>) — see the 2D mesh &amp; WebGPU subsystem.</li></ul>',12)])])}const u=o(s,[["render",r]]);export{h as __pageData,u as default};
